 for(const c of claims){const card=el('section',null,'claim');card.append(el('h4',c.office_literal||'Office not recorded'),fields([['Affiliation',c.affiliation_literal],['Capacity',c.capacity_status],['Role codes',C.list(c.role_codes).join(', ')],['Specialty codes',C.list(c.specialty_codes).join(', ')],['Analytical union',C.list(c.cameo_codes).join(', ')],['Support',c.support_status],['Assignment',c.assignment_status],['Origin',c.origin],['Applicability assumption',c.assumption],['Report years',C.list(c.report_years).join(', ')]]));const ids=new Set(C.list(c.evidence_occurrence_ids));const evidence=occ.filter(o=>ids.has(o.occurrence_id));if(evidence.length)card.append(button('Inspect claim evidence ('+evidence.length+')',()=>openDialog('Claim evidence · '+node.name,occurrenceList(evidence))));const sourceIds=C.list(c.evidence_ids).filter(id=>index.paragraphs.has(id));if(sourceIds.length)card.append(button('Inspect source paragraphs ('+sourceIds.length+')',()=>{const body=el('div');for(const id of sourceIds)body.append(paragraphEvidence(id));openDialog('Claim source evidence · '+node.name,body);}));const metadata=el('details');metadata.append(el('summary','Record metadata'),fields([['Saved evidence IDs',C.list(c.evidence_ids).join(', ')],['Observation basis',c.observation_basis],['Recorded status',c.technical_status]]));card.append(metadata);const reportIds=C.unique([...C.list(c.evidence_report_ids),c.source_report_id].filter(Boolean));for(const id of reportIds)card.append(reportLink(id));out.append(card);}
