function selectedReports(){return bundle.reports.filter(r=>state.reports.has(r.report_id)&&(!state.from||(r.year!=null&&r.year>=Number(state.from)))&&(!state.to||(r.year!=null&&r.year<=Number(state.to)))).map(r=>r.report_id);}
