 $('report-selection-count').textContent=reports.length+' / '+bundle.reports.length;$('construction-summary').textContent=state.workflow+' · '+state.scale+' · '+reports.length+' reports';
 const metrics=clear('network-metrics');metrics.append(metricCard(network.summary.nodes,'Actors'),metricCard(network.summary.edges,'Connections'),metricCard(network.summary.isolates,'Unconnected actors'),metricCard(reports.length,'Reports selected'));
 const scope=$('network-scope'),baseline=isBaseline();scope.className='scope-note'+(baseline?'':' exploratory');
 scope.textContent=(baseline?'UNMIL paper baseline':bundle.dataset.kind==='frozen-study'&&!trustedStudy?'Imported data · study identity unverified':'Exploratory view')+' · '+state.workflow+' / '+state.scale+'. '+(baseline?'Saved study statistics apply to this complete network.':'Saved study statistics are hidden for this selection.')+' '+network.exclusions.unassigned_identity+' unresolved observations and '+network.exclusions.missing_unit+' observations without a text unit are excluded; '+network.exclusions.outside_selection+' are outside the selection.';
 const query=state.search.trim().toLocaleLowerCase(),matches=network.nodes.filter(n=>{
   const full=index.nodes.get(C.key(state.workflow,n.actor_id)),coding=networkRoles.get(n.actor_id),role=C.rolePresentation(coding.roles);
   return (!query||[n.name,n.actor_id,...(full.aliases||[])].some(v=>String(v).toLocaleLowerCase().includes(query)))&&(!state.code||coding.union.includes(state.code))&&(!state.role||(state.role.startsWith('__')?role.code===state.role:coding.roles.includes(state.role)))&&(!state.hideIsolates||n.degree>0);
 }),ids=new Set(matches.map(n=>n.actor_id));
