 panel.classList.add('expanded');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');document.body.classList.add('graph-expanded');panel.append($('detail-dialog'));
 // Isolate the expanded workspace from page navigation, including on browsers without Fullscreen API support.
 for(let child=panel;child.parentElement&&child.parentElement!==document.documentElement;child=child.parentElement)for(const sibling of child.parentElement.children)if(sibling!==child&&!sibling.inert){sibling.inert=true;sibling.dataset.graphInert='';}
 $('graph-fullscreen').textContent='Exit full screen';$('graph-fullscreen').setAttribute('aria-expanded','true');
 try{if(panel.requestFullscreen)await panel.requestFullscreen();}catch{/* A full-window workspace is the supported fallback. */}
