 if(isBaseline()){const original=(bundle.networks||[]).find(n=>n.workflow===state.workflow&&n.scale===state.scale)?.nodes.find(n=>n.actor_id===node.actor_id);if(original?.published_metrics){const details=el('details');details.append(el('summary','Study statistics'),fields(Object.entries(original.published_metrics)),note('Saved study values, available only for the exact baseline.'));out.append(details);}}
